import { atom, read, update } from 'claude-code'
import type {
  EngineInterface,
  ModelEffort,
  PluginOptions,
  Register,
} from 'claude-code'

import type { Held, LogKind, LogLine, Menu, Target, TargetChoice } from '../types'
import { CHOICES, GUIDES, isChoice, targetOf } from './guides'
import { cardsPane } from './cards'
import type { CardsView } from './cards'
import {
  easyOf,
  EFFORTS,
  fmtClock,
  isEffort,
  isPolishable,
  modelsOf,
  polishedOf,
  requestOf,
  rowsOf,
} from './polish'
import type { Polished } from './polish'
import {
  answerOf,
  filesOf,
  mentionedIn,
  pathsOf,
  projectOf,
  SKIPPED_DIRS,
} from './project'
import type { Read } from './project'

const PANE = 'prompt-polish'
const TITLE = 'Prompt Polish'
const PANE_COLUMNS = 71
const IDLE_ROWS = 9
const LOG_ROWS = 8
const HINT_MS = 5000
// How many polishes of one draft are kept to page through.
const VERSIONS = 10

// Theme keys, so the pane follows the person's theme.
const C = {
  main: 'claude',
  polished: 'suggestion',
  ok: 'success',
  warn: 'error',
  amber: 'warning',
  dim: 'inactive',
  faint: 'subtle',
  // The words on an accent block.
  onMain: 'inverseText',
} as const

// OpenAI's brand green, for a pane polishing a prompt a GPT model will read.
const GPT_GREEN = '#10A37F'
const GPT_TARGETS: readonly Target[] = ['gpt-6-astra', 'gpt-5.6']

// The key of each button, by the button's own key. A button drawn as a block
// of color shows the key it has, so it has one only while the keys are listed.
const HOTKEYS: Record<string, string> = {
  polish: 'p',
  apply: 'y',
  refresh: 'r',
  discard: 'x',
  restore: 'u',
  older: 'b',
  newer: 'n',
  cancel: 'c',
  auto: 'a',
  target: 't',
  polisher: 'm',
  log: 'l',
  keys: 'k',
}

const KEYS = [
  ['p', 'Prompt Polish'],
  ['y', 'Apply Polish'],
  ['r', 'Retry Polish'],
  ['x', 'Keep Original'],
  ['u', 'Undo Apply'],
  ['b', 'Older Version'],
  ['n', 'Newer Version'],
  ['c', 'Stop'],
  ['a', 'AUTO'],
  ['t', 'Session Model'],
  ['m', 'Polish Model'],
  ['1-9', 'Pick from an open list'],
  ['l', 'History'],
  ['k', 'Keys'],
  ['Tab', 'Next button'],
  ['Enter', 'Press'],
] as const

const LOG: Record<LogKind, { label: string; color: string }> = {
  polish: { label: 'Polished', color: C.polished },
  refresh: { label: 'Retried', color: C.polished },
  apply: { label: 'Applied', color: C.ok },
  keep: { label: 'Kept', color: C.dim },
  fail: { label: 'Failed', color: C.warn },
}

const isAuto = atom({ plugin: 'prompt-polish', key: 'isAuto' } as const, true)
const target = atom({ plugin: 'prompt-polish', key: 'target' } as const, 'auto')
const isBusy = atom({ plugin: 'prompt-polish', key: 'isBusy' } as const, false)
const busySince = atom(
  { plugin: 'prompt-polish', key: 'busySince' } as const,
  null,
)
const menu = atom({ plugin: 'prompt-polish', key: 'menu' } as const, null)
const original = atom(
  { plugin: 'prompt-polish', key: 'original' } as const,
  null,
)
const proposal = atom(
  { plugin: 'prompt-polish', key: 'proposal' } as const,
  null,
)
const versions = atom({ plugin: 'prompt-polish', key: 'versions' } as const, [])
const version = atom({ plugin: 'prompt-polish', key: 'version' } as const, 0)
const held = atom({ plugin: 'prompt-polish', key: 'held' } as const, null)
const isReviewed = atom(
  { plugin: 'prompt-polish', key: 'isReviewed' } as const,
  false,
)
const log = atom({ plugin: 'prompt-polish', key: 'log' } as const, [])
const isLogOpen = atom(
  { plugin: 'prompt-polish', key: 'isLogOpen' } as const,
  false,
)
const isKeysOpen = atom(
  { plugin: 'prompt-polish', key: 'isKeysOpen' } as const,
  false,
)
const isGuideOpen = atom(
  { plugin: 'prompt-polish', key: 'isGuideOpen' } as const,
  false,
)
const hintUntil = atom(
  { plugin: 'prompt-polish', key: 'hintUntil' } as const,
  null,
)
const isPlain = atom({ plugin: 'prompt-polish', key: 'isPlain' } as const, false)
const models = atom({ plugin: 'prompt-polish', key: 'models' } as const, [])
const model = atom({ plugin: 'prompt-polish', key: 'model' } as const, null)
const effort = atom({ plugin: 'prompt-polish', key: 'effort' } as const, null)

// The polish a button press started, for the Cancel press that follows it.
let stop: AbortController | null = null

type Proposed = { isProposed: boolean; note: string }

const resolveTarget = async ($: EngineInterface): Promise<Target> => {
  const choice = await read($, target)

  return choice === 'auto' ? targetOf(await $.session.model()) : choice
}

/** How a choice of the model the prompt is for reads: its guide's name, or what "auto" came to. */
const choiceLabel = (choice: TargetChoice, resolved: Target): string =>
  choice === 'auto'
    ? `${GUIDES[resolved].label} (Detected)`
    : GUIDES[choice].label

/** The model and effort that polish: the pane's picks over the mod's options. */
const pickedOf = async (
  $: EngineInterface,
  options: PluginOptions,
): Promise<{ polishModel: string; effort: ModelEffort }> => {
  const level = (await read($, effort)) ?? options.effort

  return {
    polishModel: (await read($, model)) ?? String(options.polishModel ?? 'sonnet'),
    effort: isEffort(level) ? level : 'low',
  }
}

const loadModels = async ($: EngineInterface): Promise<void> => {
  const rows = await $.config.list().catch(() => [])
  const listed = rows.find(row => row.key === 'model')?.options ?? []
  const list = modelsOf(listed, await $.session.model())
  await update($, models, () => list)
}

const toggleLog = async ($: EngineInterface): Promise<void> => {
  await update($, isLogOpen, isOpen => !isOpen)
}

const toggleKeys = async ($: EngineInterface): Promise<void> => {
  await update($, isKeysOpen, isOpen => !isOpen)
}

const toggleGuide = async ($: EngineInterface): Promise<void> => {
  await update($, isGuideOpen, isOpen => !isOpen)
}

const toggleMenu = async ($: EngineInterface, which: Menu): Promise<void> => {
  await update($, menu, shown => (shown === which ? null : which))
}

const closeMenu = async ($: EngineInterface): Promise<void> => {
  await update($, menu, () => null)
}

const pickTarget = async ($: EngineInterface, value: string): Promise<void> => {
  if (!isChoice(value)) {
    return
  }

  await update($, menu, () => null)
  await update($, target, () => value)
  await $.store.set('target', value)
}

const pickModel = async ($: EngineInterface, value: string): Promise<void> => {
  await update($, model, () => value)
  await $.store.set('model', value)
}

const pickEffort = async ($: EngineInterface, value: string): Promise<void> => {
  if (!isEffort(value)) {
    return
  }

  await update($, effort, () => value)
  await $.store.set('effort', value)
}

const say = async (
  $: EngineInterface,
  kind: LogKind,
  text: string,
): Promise<void> => {
  const line: LogLine = { at: await $.clock.now(), kind, text }
  await update($, log, lines => [...lines, line].slice(-30))
}

/**
 * Opens the pane, or resizes the open one: `columns` docked beside a
 * fullscreen transcript, `rows` inline above the prompt. `isAsking` asks for
 * the keyboard, which the surface gives over an empty prompt box.
 */
const openPane = ($: EngineInterface, rows: number, isAsking: boolean) =>
  $.ui.open({
    id: PANE,
    title: TITLE,
    columns: PANE_COLUMNS,
    rows,
    ...(isAsking ? ({ focus: true } as const) : {}),
  })

// Nothing hands a pane's keyboard back but its close: closed and opened
// again, the pane stays up and the prompt box has the keys for Enter.
const rest = async ($: EngineInterface): Promise<void> => {
  await $.ui.close({ id: PANE })
  await openPane($, IDLE_ROWS, false)
}

const WALK_DEPTH = 3
const WALK_FILES = 2_000

/** The project's files by walking it, where git cannot list them. */
const walk = async ($: EngineInterface, root: string): Promise<string[]> => {
  const found: string[] = []
  const visit = async (dir: string, depth: number): Promise<void> => {
    const entries = await $.fs.list(dir === '' ? root : `${root}/${dir}`).catch(() => [])

    for (const entry of entries) {
      const path = dir === '' ? entry.name : `${dir}/${entry.name}`

      if (found.length >= WALK_FILES) {
        return
      }

      if (entry.kind === 'file') {
        found.push(path)
      } else if (
        entry.kind === 'dir' &&
        depth < WALK_DEPTH &&
        !SKIPPED_DIRS.includes(entry.name)
      ) {
        await visit(path, depth + 1)
      }
    }
  }

  await visit('', 0)

  return found
}

const listed = async ($: EngineInterface, root: string): Promise<string[]> => {
  // What git tracks, and what it neither tracks nor ignores; a name outside
  // ASCII as it is written, not escaped.
  const git = await $.process
    .run(
      [
        'git',
        '-c',
        'core.quotepath=false',
        'ls-files',
        '--cached',
        '--others',
        '--exclude-standard',
      ],
      { cwd: root, timeoutMs: 10_000 },
    )
    .catch(() => undefined)

  return git !== undefined && git.exitCode === 0 && git.stdout.trim() !== ''
    ? pathsOf(git.stdout)
    : pathsOf((await walk($, root)).join('\n'))
}

const readerOf =
  ($: EngineInterface, root: string): Read =>
  async path => {
    const text = await $.fs.read(`${root}/${path}`).catch(() => undefined)

    // A NUL says the file is not text, whatever its name.
    return text === undefined || text.includes('\0') ? undefined : text
  }

/** The start of each file `draft` names, then of those `answer` names, among `paths`. */
const namedOf = (
  paths: readonly string[],
  draft: string,
  answer: string,
  read: Read,
): Promise<string> =>
  filesOf(
    [...new Set([...mentionedIn(draft, paths), ...mentionedIn(answer, paths)])],
    read,
  )

/**
 * Reads what one polish is given besides the draft: the project as it stands
 * on disk, the files the draft and the last answer name, and that answer.
 * Nothing here calls a model.
 */
const gather = async ($: EngineInterface, draft: string): Promise<Held> => {
  const answer = answerOf(await $.session.messages().catch(() => []))
  const root = await $.session.root().catch(() => undefined)

  if (root === undefined) {
    return { project: '', files: '', answer }
  }

  const paths = await listed($, root)
  const read = readerOf($, root)

  return {
    project: await projectOf(paths, read),
    files: await namedOf(paths, draft, answer, read),
    answer,
  }
}

/**
 * What a retry of an edited draft is given: the project and the answer as
 * its polish read them, and the files the draft now names.
 */
const regather = async (
  $: EngineInterface,
  kept: Held,
  draft: string,
): Promise<Held> => {
  const root = await $.session.root().catch(() => undefined)

  if (root === undefined) {
    return kept
  }

  const paths = await listed($, root)

  return {
    ...kept,
    files: await namedOf(paths, draft, kept.answer, readerOf($, root)),
  }
}

const polish = async (
  $: EngineInterface,
  draft: string,
  guide: Target,
  given: Held,
  options: PluginOptions,
  signal: AbortSignal,
  rejected?: string,
): Promise<Polished> => {
  const request = requestOf(
    { draft, target: guide, held: given, rejected },
    { ...options, ...(await pickedOf($, options)) },
  )

  return polishedOf(await $.model.complete(request, { signal }))
}

/**
 * Polishes `draft` and holds the result as the proposal the pane previews;
 * the prompt box is left as it is. `rejected` is an earlier proposal of the
 * same draft, to polish away from.
 *
 * A polish reads the project and the last answer anew. A retry is given what
 * its polish read, unchanged, so the request opens as the last one did and
 * the prompt cache serves that part again; of a draft edited since, the files
 * it now names are read, and the rest is as it was.
 */
const propose = async (
  $: EngineInterface,
  draft: string,
  options: PluginOptions,
  rejected?: string,
): Promise<Proposed> => {
  if (await read($, isBusy)) {
    return { isProposed: false, note: 'Already polishing. Please wait.' }
  }

  if (draft.trim() === '') {
    return {
      isProposed: false,
      note: 'Nothing to polish. Type a prompt first.',
    }
  }

  const mine = new AbortController()
  stop = mine
  const startedAt = await $.clock.now()
  await update($, busySince, () => startedAt)
  await update($, isBusy, () => true)
  $.ui.status('Polishing prompt…')

  // The loading mark is the pane's: a polish begun with the pane closed opens it.
  if (!(await $.ui.panes()).some(pane => pane.id === PANE)) {
    await openPane($, IDLE_ROWS, false)
  }

  try {
    const guide = await resolveTarget($)
    const kept = rejected === undefined ? null : await read($, held)
    const isEdited = draft.trim() !== (await read($, original))?.trim()
    const given =
      kept === null
        ? await gather($, draft)
        : isEdited
          ? await regather($, kept, draft)
          : kept
    await update($, held, () => given)
    const result = await polish(
      $,
      draft,
      guide,
      given,
      options,
      mine.signal,
      rejected,
    )

    // A reply that raced the Cancel press is dropped with it.
    if (mine.signal.aborted) {
      return { isProposed: false, note: 'Polish stopped.' }
    }

    if (!result.isPolished) {
      await say($, 'fail', result.reason)

      return { isProposed: false, note: `Polish failed. ${result.reason}.` }
    }

    if (result.text === draft.trim()) {
      await say($, 'keep', 'No changes')

      return {
        isProposed: false,
        note: 'Already clear. No changes.',
      }
    }

    const text = result.text
    // A retry of the same draft adds a version to those made of it, unless it
    // came to one of them again; a polish, or a retry of a draft edited
    // since, starts them over.
    const earlier =
      rejected === undefined || isEdited ? [] : await read($, versions)
    const again = earlier.indexOf(text)
    const made = (again === -1 ? [...earlier, text] : earlier).slice(-VERSIONS)
    await update($, original, () => draft)
    await update($, versions, () => made)
    await update($, version, () => (again === -1 ? made.length - 1 : again))
    await update($, proposal, () => text)
    await update($, isReviewed, () => true)
    await say(
      $,
      rejected === undefined ? 'polish' : 'refresh',
      `${GUIDES[guide].label} · ${draft.trim().length} → ${text.length} chars`,
    )
    await openPane($, rowsOf(draft, text), true)

    return {
      isProposed: true,
      note: `Polished for ${GUIDES[guide].label}. Check it, then apply or keep.`,
    }
  } finally {
    stop = null
    $.ui.status(undefined)
    await update($, isBusy, () => false)
    await update($, busySince, () => null)
  }
}

const polishBox = async (
  $: EngineInterface,
  options: PluginOptions,
): Promise<void> => {
  const box = (await $.prompt.read()).text
  $.ui.toast((await propose($, box, options)).note)
}

/** Polishes again, away from the proposal on show: the box's draft, or the one it was made from. */
const refresh = async (
  $: EngineInterface,
  options: PluginOptions,
): Promise<void> => {
  const shown = await read($, proposal)
  const draft = await read($, original)

  if (shown === null || draft === null) {
    return
  }

  const box = (await $.prompt.read()).text
  const again = box.trim() === '' ? draft : box
  $.ui.toast((await propose($, again, options, shown)).note)
}

/** Puts the version before or after the one on preview there in its place. */
const step = async ($: EngineInterface, by: -1 | 1): Promise<void> => {
  const at = (await read($, version)) + by
  const text = (await read($, versions))[at]

  if (text === undefined || (await read($, proposal)) === null) {
    return
  }

  await update($, version, () => at)
  await update($, proposal, () => text)
}

/** Puts the proposal in the prompt box, keeping what the box held for Undo. */
const apply = async ($: EngineInterface): Promise<void> => {
  const text = await read($, proposal)
  const draft = await read($, original)

  if (text === null) {
    return
  }

  const box = (await $.prompt.read()).text
  const filled = await $.prompt.fill({ text })

  if (!filled.isFilled) {
    $.ui.toast('Could not change the prompt box.')

    return
  }

  const kept = box.trim() === '' ? draft : box
  await update($, proposal, () => null)
  await update($, versions, () => [])
  await update($, held, () => null)
  await update($, original, () => kept)
  await say($, 'apply', `${text.length} chars`)
  await rest($)
  $.ui.toast('Applied. Press Enter to send.')
}

/** Drops the proposal; a prompt box the held draft left empty gets it back. */
const keep = async ($: EngineInterface): Promise<void> => {
  const draft = await read($, original)

  if ((await read($, proposal)) === null) {
    return
  }

  if (draft !== null && (await $.prompt.read()).text.trim() === '') {
    await $.prompt.fill({ text: draft })
  }

  await update($, proposal, () => null)
  await update($, versions, () => [])
  await update($, original, () => null)
  await say($, 'keep', 'Original kept')
}

const discard = async ($: EngineInterface): Promise<void> => {
  await keep($)
  await rest($)
}

const restore = async ($: EngineInterface): Promise<void> => {
  const draft = await read($, original)

  if (draft === null) {
    return
  }

  const filled = await $.prompt.fill({ text: draft })

  if (filled.isFilled) {
    await update($, original, () => null)
  }
}

const settle = async ($: EngineInterface): Promise<void> => {
  if ((await read($, proposal)) !== null) {
    await update($, proposal, () => null)
    await update($, versions, () => [])
  }

  if ((await read($, original)) !== null) {
    await update($, original, () => null)
  }

  if (await read($, isReviewed)) {
    await update($, isReviewed, () => false)
  }
}

// Takes down the note a switch of AUTO put up, unless a later switch renewed it.
const hideHint = async ($: EngineInterface, until: number): Promise<void> => {
  await update($, hintUntil, shown => (shown === until ? null : shown))
}

/** Switches AUTO, and says for a few seconds what Enter does from now on. */
const toggleAuto = async ($: EngineInterface): Promise<void> => {
  const isOn = !(await read($, isAuto))
  const until = (await $.clock.now()) + HINT_MS
  await update($, isAuto, () => isOn)
  await update($, hintUntil, () => until)
  await $.store.set('isAuto', isOn)
  $.clock.after(HINT_MS, () => void hideHint($, until))
}

/** What each control of the cards does, by the name the cards have for it. */
const actsOf = (
  $: EngineInterface,
  options: PluginOptions,
): CardsView['act'] => ({
  guide: () => void toggleGuide($),
  auto: () => void toggleAuto($),
  menu: which => void toggleMenu($, which),
  done: () => void closeMenu($),
  target: value => void pickTarget($, value),
  model: value => void pickModel($, value),
  effort: value => void pickEffort($, value),
  polish: () => void polishBox($, options),
  apply: () => void apply($),
  retry: () => void refresh($, options),
  keep: () => void discard($),
  undo: () => void restore($),
  stop: () => stop?.abort(),
  step: by => void step($, by),
  log: () => void toggleLog($),
  keys: () => void toggleKeys($),
})

/** The key a catcher posted (hit.tsx), when the post is one. */
const pressOf = (data: unknown): string | undefined =>
  typeof data === 'object' &&
  data !== null &&
  'press' in data &&
  typeof data.press === 'string'
    ? data.press
    : undefined

/**
 * Does what the control keyed `key` does, when the pane as it stands draws
 * that control. A catcher's post is input from the surface, and may name a
 * control a redraw has taken away since the click began.
 */
const pressed = async (
  $: EngineInterface,
  options: PluginOptions,
  key: string,
): Promise<void> => {
  const act = actsOf($, options)

  // Drawn in every state: the heading's line, the record and the keys.
  if (key === 'guide') {
    return act.guide()
  }

  if (key === 'log') {
    return act.log()
  }

  if (key === 'keys') {
    return act.keys()
  }

  // While a polish runs the settings and the working row are gone.
  if (await read($, isBusy)) {
    return key === 'cancel' ? act.stop() : undefined
  }

  if (key === 'auto') {
    return act.auto()
  }

  if (key === 'target' || key === 'polisher') {
    return act.menu(key)
  }

  const open = await read($, menu)

  if (open === 'target' && key.startsWith('target-')) {
    return act.target(key.slice('target-'.length))
  }

  if (open === 'polisher') {
    if (key === 'polisher-done') {
      return act.done()
    }

    if (key.startsWith('effort-')) {
      return act.effort(key.slice('effort-'.length))
    }

    const name = key.startsWith('model-') ? key.slice('model-'.length) : ''
    const offered = [
      (await pickedOf($, options)).polishModel,
      ...(await read($, models)),
    ]

    if (offered.includes(name)) {
      return act.model(name)
    }
  }

  if ((await read($, proposal)) === null) {
    return key === 'polish'
      ? act.polish()
      : key === 'restore'
        ? act.undo()
        : undefined
  }

  switch (key) {
    case 'apply':
      return act.apply()
    case 'refresh':
      return act.retry()
    case 'discard':
      return act.keep()
    case 'older':
      return act.step(-1)
    case 'newer':
      return act.step(1)
    default:
      return undefined
  }
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    const savedAuto = await $.store.get('isAuto')
    const savedTarget = await $.store.get('target')

    if (typeof savedAuto === 'boolean') {
      await update($, isAuto, () => savedAuto)
    }

    if (isChoice(savedTarget)) {
      await update($, target, () => savedTarget)
    }

    const savedModel = await $.store.get('model')
    const savedEffort = await $.store.get('effort')

    if (typeof savedModel === 'string' && savedModel !== '') {
      await update($, model, () => savedModel)
    }

    if (isEffort(savedEffort)) {
      await update($, effort, () => savedEffort)
    }

    const savedPlain = await $.store.get('isPlain')

    if (typeof savedPlain === 'boolean') {
      await update($, isPlain, () => savedPlain)
    }

    await loadModels($)

    // A reload mid-polish drops the call and would leave the pane busy.
    await update($, isBusy, () => false)
    await update($, busySince, () => null)
    await update($, menu, () => null)
    await update($, hintUntil, () => null)
    // Rows a session kept from an earlier build read as today's do.
    await update($, log, lines =>
      lines.map(line => ({ ...line, text: easyOf(line.text) })),
    )
    // One command under two names: `/polish`, and `/p_polish` beside it.
    await $.command.register({
      name: 'polish',
      description:
        'Prompt Polish: open the pane, polish a prompt, or change settings',
      argumentHint:
        '[prompt | auto | target <name> | model <name> | effort <level> | plain | close]',
    })
    await $.command.register({
      name: 'p_polish',
      description:
        'Prompt Polish: open the pane, polish a prompt, or change settings',
      argumentHint:
        '[prompt | auto | target <name> | model <name> | effort <level> | plain | close]',
    })

    if (options.openOnStart !== false) {
      void openPane($, IDLE_ROWS, false).catch(() => undefined)
    }

    return next(e)
  })

  on('command.run', { command: ['polish', 'p_polish'] }, async ($, e) => {
    const word = e.args.trim()

    if (word === 'auto') {
      await toggleAuto($)

      return {
        text: `AUTO: ${(await read($, isAuto)) ? 'ON' : 'OFF'}`,
      }
    }

    if (word === 'target' || word.startsWith('target ')) {
      const name = word.slice(6).trim()

      if (name !== '' && !isChoice(name)) {
        return {
          text: `"${name}" is not an option.\nOptions: ${CHOICES.join(', ')}`,
        }
      }

      await pickTarget($, name)
      const label = choiceLabel(await read($, target), await resolveTarget($))

      return {
        text:
          name === ''
            ? `Session Model: ${label}\nOptions: ${CHOICES.join(', ')}`
            : `Session Model: ${label}`,
      }
    }

    if (word === 'model' || word.startsWith('model ')) {
      const name = word.slice(5).trim()

      if (name === '') {
        const now = (await pickedOf($, options)).polishModel

        return {
          text: `Polish Model: ${now}\nOptions: ${(await read($, models)).join(', ')}`,
        }
      }

      await pickModel($, name)

      return { text: `Polish Model: ${name}` }
    }

    if (word === 'effort' || word.startsWith('effort ')) {
      const level = word.slice(6).trim()

      if (!isEffort(level)) {
        const now = (await pickedOf($, options)).effort

        return { text: `Effort: ${now}\nOptions: ${EFFORTS.join(', ')}` }
      }

      await pickEffort($, level)

      return { text: `Effort: ${level}` }
    }

    // The way out, should a surface's catchers ever take clicks and lose them.
    if (word === 'plain') {
      const isOff = !(await read($, isPlain))
      await update($, isPlain, () => isOff)
      await $.store.set('isPlain', isOff)

      return {
        text: isOff
          ? 'Plain buttons: ON. A control is clicked on its words alone.'
          : 'Plain buttons: OFF. A control is clicked anywhere on it.',
      }
    }

    if (word === 'close') {
      await $.ui.close({ id: PANE })

      return { text: 'Prompt Polish closed.' }
    }

    const draft = word === '' ? (await $.prompt.read()).text : e.args

    if (draft.trim() === '') {
      const opened = await openPane($, IDLE_ROWS, false)

      if (!opened.isPlaced) {
        return { text: `Prompt Polish is not shown yet. ${opened.reason}` }
      }

      // The chord is a terminal's; on any other surface the pane is clicked.
      const surfaces: readonly string[] = await $.session
        .surfaces()
        .catch(() => [])

      return {
        text: surfaces.includes('terminal')
          ? 'Prompt Polish opened. Press ctrl+x tab to use its keys.'
          : 'Prompt Polish opened.',
      }
    }

    return { text: (await propose($, draft, options)).note }
  })

  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind !== 'composer') {
      return next(e)
    }

    // Auto mode holds a prompt back once, for its preview; the Enter after
    // that sends what the box holds.
    const isHeld =
      (await read($, isAuto)) && !(await read($, isReviewed)) && isPolishable(e)

    if (!isHeld) {
      await settle($)

      return next(e)
    }

    const proposed = await propose($, e.text, options)

    if (!proposed.isProposed) {
      $.ui.toast(`Sent as written. ${proposed.note}`)
      await settle($)

      return next(e)
    }

    return {
      drop: 'Not sent yet. Pick Apply Polish or Keep Original, then press Enter again.',
    }
  }).catch(($, e, next) => next(e))

  // The person closing the pane over a preview is "keep my draft".
  on('ui.close', { id: PANE }, async ($, e, next) => {
    if (e.origin.kind === 'person') {
      await keep($)
    }

    return next(e)
  })

  // A click a catcher took over one of the cards' controls, posted by key.
  on('ui.message', async ($, e, next) => {
    const key =
      e.requestId === PANE && e.module.endsWith('hit.tsx')
        ? pressOf(e.data)
        : undefined

    if (key !== undefined) {
      await pressed($, options, key)
    }

    return next(e)
  })

  // A catcher that failed would lie dead over its control. The engine draws
  // the pane again after a fault: without catchers, on its buttons alone.
  on('ui.fault', async ($, e, next) => {
    if (e.module.endsWith('hit.tsx')) {
      await update($, isPlain, () => true)
    }

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Button, Text } = els
    const isOn = await read($, isAuto)
    const isRunning = await read($, isBusy)
    const choice = await read($, target)
    const preview = await read($, proposal)
    const made = await read($, versions)
    const shownAt = await read($, version)
    const draft = await read($, original)
    const lines = await read($, log)
    const picked = await pickedOf($, options)
    const offered = [
      picked.polishModel,
      ...(await read($, models)).filter(name => name !== picked.polishModel),
    ]

    const resolved = await resolveTarget($)
    // What "auto" comes to, whichever model is picked: its row in the list
    // names the session's model, not the pick.
    const detected =
      choice === 'auto' ? resolved : targetOf(await $.session.model())
    const guide = GUIDES[resolved].label
    // The pane wears the colors of the family the prompt is for: Claude's
    // from the theme, or one green on every box for a GPT model.
    const isGpt = GPT_TARGETS.includes(resolved)
    const P = isGpt
      ? { main: GPT_GREEN, polished: GPT_GREEN, box: GPT_GREEN, rest: GPT_GREEN }
      : { main: C.main, polished: C.polished, box: C.faint, rest: C.dim }
    const W = Math.max(40, e.props.bodyColumns)
    const since = await read($, busySince)
    const isLogShown = await read($, isLogOpen)
    const isGuideShown = await read($, isGuideOpen)
    const isKeysShown = await read($, isKeysOpen)
    const open = await read($, menu)
    const now = await $.clock.now()

    // Off the terminal's grid of cells the pane is another drawing made of
    // the same state: the cards of cards.tsx. What a surface module draws
    // there is made here, where the engine reads the modules' paths from.
    if (e.surface !== 'terminal') {
      const table = $.ui.resolve(e)
      // Off the grid the desktop alone runs surface modules. The others'
      // tables hold the element too, and draw an empty box for it.
      const Client =
        e.surface === 'desktop' && 'Client' in table ? table.Client : undefined
      const kind = isRunning ? 'busy' : preview !== null ? 'review' : 'idle'
      const hue =
        kind === 'busy' ? P.main : kind === 'review' ? P.polished : C.ok
      const status = (
        <table.Box alignItems="center" columnGap={1} flexShrink={0}>
          {Client !== undefined ? (
            <Client key="pulse" module="./pulse.tsx" props={{ kind, color: hue }} />
          ) : (
            <table.Text color={hue}>●</table.Text>
          )}
          <table.Text {...(kind === 'idle' ? { dimColor: true } : { color: hue })}>
            {kind === 'busy' ? 'Polishing' : kind === 'review' ? 'Review' : 'Ready'}
          </table.Text>
        </table.Box>
      )
      const clock =
        isRunning && Client !== undefined ? (
          <Client
            key="spinner"
            module="./spinner.tsx"
            props={{ since: since ?? now, now, color: P.main }}
          />
        ) : null
      // There, a catcher over each control (hit.tsx), unless they were
      // switched off or one of them failed.
      const catcher =
        Client !== undefined && !(await read($, isPlain))
          ? (key: string, rows: number) => (
              <table.Box position="absolute" top={0} bottom={0} left={0} right={0}>
                <Client
                  key={`hit-${key}`}
                  module="./hit.tsx"
                  props={{ press: key, rows }}
                  width="100%"
                  height="100%"
                />
              </table.Box>
            )
          : undefined

      return cardsPane(
        table,
        {
          isOn,
          isRunning,
          isGpt,
          guide,
          about: GUIDES[resolved].about,
          isGuideShown,
          targets: CHOICES.map(value => ({
            value,
            label: choiceLabel(value, detected),
          })),
          target: choice,
          models: offered,
          model: picked.polishModel,
          effort: picked.effort,
          open,
          draft,
          preview,
          version: shownAt,
          versions: made.length,
          count: lines.length,
          recent: lines.slice(-LOG_ROWS),
          kinds: LOG,
          isLogShown,
          isKeysShown,
          keys: KEYS,
          hotkeys: HOTKEYS,
          status,
          clock,
          ...(catcher === undefined ? {} : { catcher }),
          act: actsOf($, options),
        },
        e.props.placement === 'dock',
        e.props.scroll.bodyRows,
      )
    }

    // A pick list of the pane's own: every row a Button, so a click picks as
    // Enter under the focus does. A bracketed Button keeps its key and draws
    // none: the keys are listed under the Keys toggle, for who wants them.
    // The button that matters now is a block of the pane's accent with its
    // words inside, as the buttons of charmbracelet/lipgloss and gum are; the
    // rest are their words alone, a space each side, with no block behind. A click presses it, and Tab then Enter;
    // its key shows before it, and works, only while the keys are listed.
    const chip = (
      key: string,
      label: string,
      isMain: boolean,
      onPress: () => void,
      isFirst = false,
    ) => (
      <Button
        key={key}
        plain
        {...(isKeysShown && HOTKEYS[key] !== undefined
          ? { hotkey: HOTKEYS[key] }
          : {})}
        {...(isFirst ? ({ autoFocus: true } as const) : {})}
        onPress={onPress}
      >
        {isMain ? (
          <Text backgroundColor={P.main} color={C.onMain} bold>
            {` ${label} `}
          </Text>
        ) : (
          <Text>{` ${label} `}</Text>
        )}
      </Button>
    )

    // A pick list of the pane's own, as gum's choose draws one: a row to an
    // option, the one in use behind a cursor and before a tick. Every row is
    // a Button, so a click picks as Enter under the focus does.
    type Pick = 'target' | 'model' | 'effort'

    // The rows alone. `from` is how many rows the frame holds before these,
    // so the digits of two lists in one frame run on rather than clash.
    const rowsOf = (
      kind: Pick,
      rows: readonly { value: string; label: string }[],
      current: string,
      from = 0,
    ) =>
      rows.map((row, i) => (
        <Button
          key={`${kind}-${row.value}`}
          plain
          {...(isKeysShown && from + i < 9
            ? { hotkey: String(from + i + 1) }
            : {})}
          onPress={() =>
            void (kind === 'target'
              ? pickTarget($, row.value)
              : kind === 'model'
                ? pickModel($, row.value)
                : pickEffort($, row.value))
          }
        >
          {row.value === current ? (
            <Text color={P.main} bold>{`> ${row.label} ✓`}</Text>
          ) : (
            <Text>{`  ${row.label}`}</Text>
          )}
        </Button>
      ))

    const optionsOf = (
      kind: Pick,
      rows: readonly { value: string; label: string }[],
      current: string,
    ) => (
      <Box
        key={`${kind}-list`}
        flexDirection="column"
        borderStyle="round"
        borderColor={P.box}
        borderDimColor={isGpt}
        paddingX={1}
      >
        {rowsOf(kind, rows, current)}
      </Box>
    )

    const mark = (kind: Menu) => (open === kind ? '▴' : '▾')
    const plain = (values: readonly string[]) =>
      values.map(value => ({ value, label: value }))

    // What Enter does under each setting of AUTO, said alike; up only for a
    // few seconds after a switch, in a frame right under the line the switch
    // is on, as an open pick list is.
    const hint =
      (await read($, hintUntil)) === null
        ? null
        : isOn
          ? 'AUTO ON · Enter polishes first and shows you before sending.'
          : 'AUTO OFF · Enter sends right away, with no polish.'

    // What the prompt is for: the switch, and the model that will read it.
    const pickers = (
      <Box flexDirection="column">
        <Box columnGap={2} flexWrap="wrap">
          {chip('auto', `AUTO ${isOn ? 'ON' : 'OFF'}`, isOn, () => void toggleAuto($))}
          {chip(
            'target',
            `Session Model : ${choiceLabel(choice, resolved)} ${mark('target')}`,
            false,
            () => void toggleMenu($, 'target'),
          )}
        </Box>
        {hint !== null && (
          <Box
            key="hint"
            borderStyle="round"
            borderColor={P.box}
            borderDimColor={isGpt}
            paddingX={1}
          >
            <Text color={P.main} wrap="wrap">
              {hint}
            </Text>
          </Box>
        )}
        {open === 'target' &&
          optionsOf(
            'target',
            CHOICES.map(value => ({ value, label: choiceLabel(value, detected) })),
            choice,
          )}
      </Box>
    )

    // How hard, as a stepped slider: a track with a tick to a level and the
    // levels named under their ticks. The ticks up to the level in use are
    // lit, and its own is the knob. A click on a tick or on a name moves the
    // knob there; so does Enter under the focus, and a name's digit while the
    // keys are listed.
    const STEP = 8
    const at = EFFORTS.indexOf(picked.effort)
    // Each name is centered under its tick. The track starts far enough in
    // for the first name's left half, and a name starts half its length left
    // of its tick; the room between two names is plain space, not button.
    const INSET = Math.floor((EFFORTS[0]?.length ?? 0) / 2)
    const nameStarts = EFFORTS.map(
      (level, i) => INSET + i * STEP - Math.floor(level.length / 2),
    )
    const slider = (
      <Box key="effort-slider" flexDirection="column">
        <Box key="effort-track">
          <Text>{' '.repeat(INSET)}</Text>
          {EFFORTS.map((level, i) => {
            const isLast = i === EFFORTS.length - 1

            // The tick alone is the button, so the focus and the pointer
            // light the tick and never the line; the line is one plain color.
            return (
              <Box>
                <Button
                  key={`effort-tick-${level}`}
                  plain
                  onPress={() => void pickEffort($, level)}
                >
                  <Text color={i <= at ? P.main : C.faint} bold={i === at}>
                    {i < at ? '•' : i === at ? '●' : '○'}
                  </Text>
                </Button>
                {!isLast && (
                  <Text color={C.faint}>{'─'.repeat(STEP - 1)}</Text>
                )}
              </Box>
            )
          })}
        </Box>
        <Box key="effort-names">
          {EFFORTS.map((level, i) => {
            const before = EFFORTS[i - 1]
            const gap =
              (nameStarts[i] ?? 0) -
              (before === undefined ? 0 : (nameStarts[i - 1] ?? 0) + before.length)

            return (
              <Box>
                <Text>{' '.repeat(Math.max(0, gap))}</Text>
                <Button
                  key={`effort-${level}`}
                  plain
                  {...(isKeysShown && offered.length + i < 9
                    ? { hotkey: String(offered.length + i + 1) }
                    : {})}
                  onPress={() => void pickEffort($, level)}
                >
                  {i === at ? (
                    <Text color={P.main} bold>
                      {level}
                    </Text>
                  ) : (
                    <Text dimColor>{level}</Text>
                  )}
                </Button>
              </Box>
            )
          })}
        </Box>
      </Box>
    )

    // Who polishes, and how hard: one button on the settings box's second
    // line, saying both. Its list is one frame as wide as the box holding the
    // models and the effort slider side by side, and it stays up after a pick,
    // so both can be set; `done`, under it at the right, folds it, as the button does.
    const tuning = (
      <Box key="tuning" flexDirection="column">
        <Box columnGap={2} flexWrap="wrap">
          {chip(
            'polisher',
            `Polish Model : ${picked.polishModel} (${picked.effort}) ${mark('polisher')}`,
            false,
            () => void toggleMenu($, 'polisher'),
          )}
        </Box>
        {open === 'polisher' && (
          <Box
            key="polisher-list"
            flexDirection="column"
            borderStyle="round"
            borderColor={P.box}
            borderDimColor={isGpt}
            paddingX={1}
          >
            {/* The models at the frame's left end and the slider at its
                right. Too narrow for both, the slider goes under the models,
                a line left empty between them. */}
            <Box
              key="polisher-body"
              justifyContent="space-between"
              columnGap={2}
              rowGap={1}
              flexWrap="wrap"
            >
              <Box key="model-list" flexDirection="column">
                <Text dimColor>Polish Model</Text>
                {rowsOf('model', plain(offered), picked.polishModel)}
              </Box>
              <Box key="effort-list" flexDirection="column">
                <Text dimColor>Effort</Text>
                {slider}
              </Box>
            </Box>
          </Box>
        )}
        {/* `done`: under the list's frame and inside the settings box, at
            the right end, as Stop is under the loading mark's. */}
        {open === 'polisher' && (
          <Box key="polisher-foot" justifyContent="flex-end">
            {chip('polisher-done', 'done', false, () => void closeMenu($))}
          </Box>
        )}
      </Box>
    )

    // The loading mark: up for as long as a polish runs, whoever began it,
    // at the foot of the settings box, in place of the settings' buttons, in
    // a frame of its own. Its bar is as long as that frame's inside: the
    // pane's width less the frame, and less the settings box where it has one.
    const loaderW = Math.max(
      8,
      W - 4 - (e.props.placement === 'inline' && preview === null ? 0 : 4),
    )
    const loader = isRunning ? (
      <Box
        key="loader"
        flexDirection="column"
        borderStyle="round"
        borderColor={P.box}
        borderDimColor={isGpt}
        paddingX={1}
      >
        <Box columnGap={1}>
          {'Client' in els ? (
            <els.Client
              key="spinner"
              module="./spinner.tsx"
              props={{ since: since ?? now, now, color: P.main }}
            />
          ) : (
            <Text color={P.main} bold>
              ●
            </Text>
          )}
          <Text color={P.main} bold>
            Polishing prompt
          </Text>
          <Text dimColor wrap="truncate">
            {`${picked.polishModel} · effort ${picked.effort}`}
          </Text>
        </Box>
        {'Client' in els && (
          <els.Client
            key="bar"
            module="./bar.tsx"
            width={loaderW}
            height={1}
            props={{ width: loaderW, color: P.main, dim: C.faint }}
          />
        )}
      </Box>
    ) : null

    // Stop: under the mark's frame and inside the settings box, the box's
    // last line, at its right end.
    const stopRow = isRunning ? (
      <Box key="loader-foot" justifyContent="flex-end">
        {chip('cancel', 'Stop', false, () => stop?.abort(), true)}
      </Box>
    ) : null

    const phase = isRunning
      ? ({ kind: 'busy', glyph: '●', text: 'Polishing', color: P.main } as const)
      : preview !== null
        ? ({ kind: 'review', glyph: '◆', text: 'Review', color: P.polished } as const)
        : ({ kind: 'idle', glyph: '●', text: 'Ready', color: C.dim } as const)

    // The state: a mark that moves where the surface can animate, still elsewhere.
    const status = (
      <Box columnGap={1} flexShrink={0}>
        {'Client' in els ? (
          <els.Client
            key="pulse"
            module="./pulse.tsx"
            props={{
              kind: phase.kind,
              color: phase.kind === 'idle' ? C.ok : phase.color,
            }}
          />
        ) : (
          <Text color={phase.kind === 'idle' ? C.ok : phase.color}>
            {phase.glyph}
          </Text>
        )}
        <Text color={phase.color} bold={phase.kind !== 'idle'}>
          {phase.text}
        </Text>
      </Box>
    )

    const actions = preview !== null ? (
      <Box columnGap={2} flexWrap="wrap">
        {chip('apply', 'Apply Polish', true, () => void apply($), true)}
        {chip('refresh', 'Retry Polish', false, () => void refresh($, options))}
        {chip('discard', 'Keep Original', false, () => void discard($))}
      </Box>
    ) : (
      <Box key="primary" columnGap={2} flexWrap="wrap">
        {chip('polish', 'Prompt Polish', true, () => void polishBox($, options))}
        {draft !== null && chip('restore', 'Undo Apply', false, () => void restore($))}
      </Box>
    )

    // The versions a retry has made of the draft on preview, paged through as
    // assistant-ui's BranchPicker pages a message's branches: the one before,
    // which of how many is on show, the one after. With one version there is
    // nothing to page, and at either end the arrow is no button.
    const arrow = (key: 'older' | 'newer', glyph: string, by: -1 | 1) =>
      made[shownAt + by] === undefined ? (
        <Text color={C.faint}>{` ${glyph} `}</Text>
      ) : (
        chip(key, glyph, false, () => void step($, by))
      )
    const pager =
      preview !== null && made.length > 1 ? (
        <Box key="versions" flexShrink={0}>
          {arrow('older', '‹', -1)}
          <Text dimColor>{`${shownAt + 1} / ${made.length}`}</Text>
          {arrow('newer', '›', 1)}
        </Box>
      ) : null

    // The pane's working row: what to do now, and at its far end the pager of
    // what a retry made. While a polish runs there is only Stop to do, which
    // stands with the loading mark, so the row is gone, pager and all.
    const actionRow = (
      <Box
        key="action-row"
        paddingX={1}
        columnGap={2}
        flexWrap="wrap"
        alignItems="flex-start"
        {...(pager === null ? {} : ({ justifyContent: 'space-between' } as const))}
        width={W}
      >
        {actions}
        {pager}
      </Box>
    )

    const rowOf = (line: LogLine) => (
      <Box>
        <Box width={9} flexShrink={0}>
          <Text color={C.faint}>{fmtClock(line.at)}</Text>
        </Box>
        <Box width={10} flexShrink={0}>
          <Text color={LOG[line.kind].color} bold wrap="truncate">
            {LOG[line.kind].label}
          </Text>
        </Box>
        <Text wrap="truncate">{line.text}</Text>
      </Box>
    )

    // The foot, a line clear of the working panels: the keys' toggle, and under it
    // the record's, which is the pane's last row. Each list opens right above
    // its own toggle, so the two rows keep their order and the last its place.
    const latest = lines.at(-1)
    // The toggle's mark: up while folded, the way its list opens; down while open.
    const fold = (isOpen: boolean) => (isOpen ? '▾' : '▴')

    const logPanel = (
      <Box key="foot" flexDirection="column" marginTop={1} width={W}>
        {isKeysShown && (
          <Box
            key="keys-list"
            flexDirection="column"
            borderStyle="round"
            borderColor={P.box}
            borderDimColor={isGpt}
            paddingX={1}
            width={W}
          >
            <Text color={C.faint} wrap="wrap">
              Keys work while this list is open. Click the pane or press ctrl+x
              tab first.
            </Text>
            <Box columnGap={3} flexWrap="wrap">
              {KEYS.map(([key, what]) => (
                <Text>
                  <Text color={P.main} bold>
                    {key}
                  </Text>
                  <Text dimColor>{` ${what}`}</Text>
                </Text>
              ))}
            </Box>
          </Box>
        )}
        <Box key="keys-row" paddingX={1}>
          {chip('keys', `Keys ${fold(isKeysShown)}`, false, () => void toggleKeys($))}
        </Box>
        {isLogShown && (
          <Box
            key="log-list"
            flexDirection="column"
            borderStyle="round"
            borderColor={P.box}
            borderDimColor={isGpt}
            paddingX={1}
            width={W}
          >
            {lines.length === 0 && (
              <Text color={C.faint}>No history yet</Text>
            )}
            {lines.slice(-LOG_ROWS).map(rowOf)}
          </Box>
        )}
        <Box key="log-row" paddingX={1} columnGap={1}>
          <Box flexShrink={0}>
            {chip('log', `History ${lines.length} ${fold(isLogShown)}`, false, () =>
              void toggleLog($),
            )}
          </Box>
          {!isLogShown && latest !== undefined && (
            <Text dimColor wrap="truncate">
              {`${fmtClock(latest.at)} ${LOG[latest.kind].label} · ${latest.text}`}
            </Text>
          )}
        </Box>
      </Box>
    )

    const clickNote =
      e.viewport?.isFullscreen === true
        ? null
        : 'No mouse clicks on this screen (fullscreen only)'

    // Inline above the prompt with nothing to review, the pane is a summary.
    if (e.props.placement === 'inline' && preview === null) {
      return (
        <Box key="pane" flexDirection="column" width={W}>
          <Box columnGap={1}>
            <Text color={P.main} bold>
              {TITLE}
            </Text>
            {status}
          </Box>
          {!isRunning && actionRow}
          {isRunning ? loader : pickers}
          {stopRow}
          {!isRunning && tuning}
          {clickNote !== null && (
            <Text color={C.faint} wrap="truncate">
              {clickNote}
            </Text>
          )}
          {logPanel}
        </Box>
      )
    }

    const settingsPanel = (
      <Box
        key="settings"
        flexDirection="column"
        borderStyle="round"
        borderColor={P.main}
        paddingX={1}
        width={W}
      >
        <Box justifyContent="space-between">
          <Button key="guide" plain onPress={() => void toggleGuide($)}>
            <Text color={P.main} bold>
              Reference : {guide} Guide
            </Text>
          </Button>
          {status}
        </Box>
        {isGuideShown && (
          <Box
            key="about"
            borderStyle="round"
            borderColor={P.box}
            borderDimColor={isGpt}
            paddingX={1}
          >
            <Text dimColor wrap="wrap">
              {GUIDES[resolved].about}
            </Text>
          </Box>
        )}
        <Box key="divider">
          <Text color={P.box} dimColor={isGpt}>
            {'─'.repeat(Math.max(1, W - 4))}
          </Text>
        </Box>
        {isRunning ? loader : pickers}
        {stopRow}
        {!isRunning && tuning}
      </Box>
    )

    const textPanel = (
      key: string,
      title: string,
      text: string,
      color: string,
      border: string,
      isDim: boolean,
      w: number,
    ) => (
      <Box
        key={key}
        flexDirection="column"
        borderStyle="round"
        borderColor={border}
        borderDimColor={isDim}
        paddingX={1}
        width={w}
      >
        <Box justifyContent="space-between">
          <Text color={color} bold>
            {title}
          </Text>
          <Text dimColor>{`${text.trim().length} chars`}</Text>
        </Box>
        <Text dimColor={isDim} wrap="wrap">
          {text.trim()}
        </Text>
      </Box>
    )

    const isWide = W >= 110
    const half = Math.floor((W - 2) / 2)
    const review =
      preview === null ? null : isWide ? (
        <Box key="review" columnGap={2}>
          {textPanel('original', 'Original Prompt', draft ?? '', C.dim, P.rest, true, half)}
          {textPanel('polished', 'Polished Prompt', preview, P.polished, P.polished, false, half)}
        </Box>
      ) : (
        <Box key="review" flexDirection="column">
          {textPanel('original', 'Original Prompt', draft ?? '', C.dim, P.rest, true, W)}
          {textPanel('polished', 'Polished Prompt', preview, P.polished, P.polished, false, W)}
        </Box>
      )

    // Docked, the pane is as tall as its room, so the foot sits on its last row.
    const isDocked = e.props.placement === 'dock'

    return (
      <Box
        key="pane"
        flexDirection="column"
        width={W}
        {...(isDocked ? { minHeight: Math.max(1, e.props.scroll.bodyRows) } : {})}
      >
        {settingsPanel}
        {review}
        {!isRunning && actionRow}
        {clickNote !== null && (
          <Box paddingX={1}>
            <Text color={C.faint} wrap="truncate">
              {clickNote}
            </Text>
          </Box>
        )}
        {isDocked && <Box key="spacer" flexGrow={1} />}
        {logPanel}
      </Box>
    )
  })
}

