// The pane where the surface is no grid of cells: the Claude desktop app, and
// the others that draw a tree their own way. There the pane is cards on the
// surface's own backgrounds, rows of a label and its control, icons, and a
// record with a dot to a row. It is made of the state the terminal's pane is
// made of, and its buttons have the terminal's keys.
//
// What such a surface draws, and so what this drawing leans on: a box's
// background and border, a text's color and weight, a drawing beside a
// button (never in one), and a button's words alone, in the surface's own
// color. A drawing with nothing for `alt` is left out, so each says what it is.
//
// A button there is as large as its words and no larger, and is named by a
// handle a redraw replaces, so a click that redraws the pane is lost on it
// (hit.tsx says how). So each control is a box with room about its words, and
// where the surface runs one, a catcher lies over the whole of it: a click on
// the icon, the chevron or the room is a click on the control.
import type { Elements, ModelEffort, RenderElement } from 'claude-code'

import type { LogKind, LogLine, Menu } from '../types'
import { iconOf, TRACK_HEIGHT, trackOf } from './icons'
import type { IconName } from './icons'
import { EFFORTS, fmtClock } from './polish'

/** The elements every surface off the grid has. */
type Table = Pick<Elements['desktop'], 'Box' | 'Button' | 'Svg' | 'Text'>

// The surface's own backgrounds and lines, by the theme keys it maps to them:
// a card a step above the pane, a list a step above a card, and a hairline.
const CARD = 'userMessageBackground'
const LIST = 'userMessageBackgroundHover'
const LINE = 'promptBorderShimmer'
// The wash behind the polished prompt, and the color of its frame and name.
const WASH = 'selectionBg'
const BLUE = 'suggestion'
// The line of the effort slider, and the stops past the one in use.
const FAINT = 'subtle'
// The frame of a card that stands over the pane, to tell it from what it covers.
const STRONG = 'promptBorder'

// A drawing takes no color from the theme, so the accent is written out: the
// clay of a Claude model, or the green of a GPT one; and a gray that stands
// on a dark page and on a light one. A tint is the accent a fifth as strong.
const CLAY = '#D97757'
const GREEN = '#10A37F'
const QUIET = '#8C8C8C'
const tintOf = (accent: string): string => `${accent}33`

const ICON = 14
const LABEL = 14
// A hairline: a twentieth of a row.
const HAIR = 0.05
// A card over the switch is placed a whole row up from the switch's foot,
// the nearest a placed box is set, and lifted this many half rows more to
// clear the switch's head: the switch is a row and a quarter, and its frame.
const TIP_LIFT = 0.8
// How wide the loading track asks to be: wider than any pane, so the surface
// draws it as wide as the room it stands in.
const TRACK_WIDTH = 2400

export type CardsView = {
  isOn: boolean
  isRunning: boolean
  isGpt: boolean
  /** The guide in use, and the line that says what it is. */
  guide: string
  about: string
  isGuideShown: boolean
  /** The model the prompt is for: the choices, and the one picked. */
  targets: readonly { value: string; label: string }[]
  target: string
  /** Who polishes: the models offered, the one picked, and how hard. */
  models: readonly string[]
  model: string
  effort: ModelEffort
  /** The pick list that is open. */
  open: Menu | null
  /** The draft on preview, the polish of it on show, and which of how many. */
  draft: string | null
  preview: string | null
  version: number
  versions: number
  /** The record: how many rows it holds, and the latest of them, which it lists. */
  count: number
  recent: readonly LogLine[]
  kinds: Record<LogKind, { label: string; color: string }>
  isLogShown: boolean
  isKeysShown: boolean
  keys: readonly (readonly [string, string])[]
  hotkeys: Record<string, string>
  /** The state's mark and word, and the mark and time of a polish that runs. */
  status: RenderElement
  clock: RenderElement | null
  /**
   * The catcher laid over the control keyed `key`, `rows` rows of it at most,
   * where the surface runs one; absent, a control is clicked on its button.
   */
  catcher?: (key: string, rows: number) => RenderElement
  act: {
    guide: () => void
    auto: () => void
    menu: (which: Menu) => void
    done: () => void
    target: (value: string) => void
    model: (value: string) => void
    effort: (value: string) => void
    polish: () => void
    apply: () => void
    retry: () => void
    keep: () => void
    undo: () => void
    stop: () => void
    step: (by: -1 | 1) => void
    log: () => void
    keys: () => void
  }
}

export const cardsPane = (
  { Box, Button, Svg, Text }: Table,
  view: CardsView,
  isDocked: boolean,
  bodyRows: number,
): RenderElement => {
  const { act } = view
  const accent = view.isGpt ? GREEN : CLAY
  // The frame of the accent: the theme's own clay where it has it.
  const edge = view.isGpt ? GREEN : 'claude'
  // Under a catcher a chevron is a drawing, and a click on it the catcher's.
  // With none it is the end of its button's words, so the click is the button's.
  const isCaught = view.catcher !== undefined

  const icon = (name: IconName, says: string, color = QUIET) => (
    <Svg source={iconOf(name, color)} alt={says} width={ICON} height={ICON} />
  )

  const hotkeyOf = (key: string, digit?: number) =>
    !view.isKeysShown
      ? {}
      : digit !== undefined
        ? digit < 9
          ? { hotkey: String(digit + 1) }
          : {}
        : view.hotkeys[key] !== undefined
          ? { hotkey: view.hotkeys[key] }
          : {}

  // One thing to click: the box `box`, what is drawn in it (its button among
  // that), and over the whole of it the catcher of the button keyed `key`.
  // The box's padding is room the catcher takes clicks in.
  const control = (
    box: string,
    key: string,
    children: JSX.Children,
    more: object = {},
    rows = 2,
  ) => (
    <Box key={box} alignItems="center" {...more}>
      {children}
      {view.catcher?.(key, rows)}
    </Box>
  )

  // A quiet button: its words, with the drawing that says what it does
  // before them, or a toggle's chevron after them. The chevron points the
  // way the toggle's list opens while it is shut, and back while it is open.
  const ghost = (
    key: string,
    label: string,
    onPress: () => void,
    drawn: {
      before?: IconName
      toggle?: { isOpen: boolean; opens: 'down' | 'up' }
      isFirst?: boolean
    } = {},
  ) => {
    const { toggle } = drawn
    const back = toggle?.opens === 'down' ? 'up' : 'down'
    const points =
      toggle === undefined ? undefined : toggle.isOpen ? back : toggle.opens

    return control(
      `${key}-set`,
      key,
      [
        drawn.before !== undefined && icon(drawn.before, label),
        <Button
          key={key}
          plain
          {...hotkeyOf(key)}
          {...(drawn.isFirst === true ? ({ autoFocus: true } as const) : {})}
          onPress={onPress}
        >
          {points === undefined || isCaught
            ? label
            : `${label} ${points === 'down' ? '▾' : '▴'}`}
        </Button>,
        points !== undefined &&
          isCaught &&
          icon(points, toggle?.isOpen === true ? 'Collapse' : 'Expand'),
      ],
      { paddingX: 1, paddingY: 0.5 },
    )
  }

  // The button to press: a box washed in the accent and framed in it.
  const filled = (
    key: string,
    label: string,
    name: IconName,
    onPress: () => void,
    isFirst = false,
  ) =>
    control(
      `${key}-block`,
      key,
      [
        icon(name, label, accent),
        <Button
          key={key}
          plain
          {...hotkeyOf(key)}
          {...(isFirst ? ({ autoFocus: true } as const) : {})}
          onPress={onPress}
        >
          {label}
        </Button>,
      ],
      {
        borderStyle: 'round',
        borderColor: edge,
        backgroundColor: tintOf(accent),
        paddingX: 2,
        paddingY: 0.5,
        overflow: 'hidden',
      },
    )

  const card = (key: string, children: JSX.Children, more: object = {}) => (
    <Box
      key={key}
      flexDirection="column"
      borderStyle="round"
      borderColor={LINE}
      backgroundColor={CARD}
      rowGap={1}
      {...more}
    >
      {children}
    </Box>
  )

  // One setting: its name, then its control.
  const row = (name: string, field: JSX.Children) => (
    <Box alignItems="center" columnGap={1}>
      <Box width={LABEL} flexShrink={0}>
        <Text dimColor>{name}</Text>
      </Box>
      {field}
    </Box>
  )

  // A pick list: a row to an option, the one in use washed and ticked. The
  // whole row is the option's to click, not its name alone.
  const options = (
    kind: 'target' | 'model',
    rows: readonly { value: string; label: string }[],
    current: string,
    pick: (value: string) => void,
  ) =>
    rows.map((option, i) =>
      control(
        `${kind}-${option.value}-row`,
        `${kind}-${option.value}`,
        [
          <Button
            key={`${kind}-${option.value}`}
            plain
            {...hotkeyOf(kind, i)}
            onPress={() => pick(option.value)}
          >
            {option.label}
          </Button>,
          option.value === current && icon('check', 'In use', accent),
        ],
        {
          justifyContent: 'space-between',
          paddingX: 1,
          paddingY: 0.25,
          ...(option.value === current
            ? { backgroundColor: tintOf(accent) }
            : {}),
        },
      ),
    )

  const list = (key: string, children: JSX.Children) => (
    <Box
      key={key}
      flexDirection="column"
      borderStyle="round"
      borderColor={LINE}
      backgroundColor={LIST}
      padding={0.5}
    >
      {children}
    </Box>
  )

  const at = EFFORTS.indexOf(view.effort)
  // How hard, as a stepped slider: a line with a stop to a level, and each
  // level named under its stop. The stops up to the level in use are lit and
  // its own is the knob, with its name lit under it; those past it are rings.
  // A level is a fifth of the line, stop and name together, and a click
  // anywhere in its fifth moves the knob there.
  const stretch = (isDrawn: boolean) => (
    <Box
      flexGrow={1}
      height={HAIR}
      {...(isDrawn ? { backgroundColor: FAINT } : {})}
    />
  )
  const efforts = (
    <Box key="effort-slider" flexDirection="column">
      <Text dimColor>Effort</Text>
      <Box key="effort-stops">
        {EFFORTS.map((level, i) =>
          control(
            `effort-${level}-set`,
            `effort-${level}`,
            [
              <Box alignItems="center">
                {stretch(i > 0)}
                <Text color={i <= at ? edge : FAINT} bold={i === at}>
                  {i < at ? '•' : i === at ? '●' : '○'}
                </Text>
                {stretch(i < EFFORTS.length - 1)}
              </Box>,
              <Box justifyContent="center">
                {i === at ? (
                  <Text key="effort-in-use" color={edge} bold>
                    {level}
                  </Text>
                ) : (
                  <Button
                    key={`effort-${level}`}
                    plain
                    dimColor
                    {...hotkeyOf('effort', view.models.length + i)}
                    onPress={() => act.effort(level)}
                  >
                    {level}
                  </Button>
                )}
              </Box>,
            ],
            {
              width: `${100 / EFFORTS.length}%`,
              flexDirection: 'column',
              alignItems: 'stretch',
              paddingY: 0.5,
            },
            3,
          ),
        )}
      </Box>
    </Box>
  )

  const targetLabel =
    view.targets.find(choice => choice.value === view.target)?.label ??
    view.target

  // While a polish runs: its mark and time, what runs, and who runs it, over
  // a dotted track a lit stretch runs along; and under them, the way to stop.
  const loader = (
    <Box key="loader" flexDirection="column" rowGap={0.5}>
      <Box
        key="working"
        flexDirection="column"
        borderStyle="round"
        borderColor={LINE}
        rowGap={1}
      >
        <Box alignItems="center" columnGap={1} flexWrap="wrap">
          {view.clock}
          <Text color={edge} bold>
            Polishing prompt
          </Text>
          <Text dimColor>{`${view.model} · effort ${view.effort}`}</Text>
        </Box>
        <Svg
          source={trackOf(accent, QUIET)}
          alt="Polishing"
          width={TRACK_WIDTH}
          height={TRACK_HEIGHT}
          isInteractive
        />
      </Box>
      <Box key="loader-foot" justifyContent="flex-end">
        {ghost('cancel', 'Stop', act.stop, { before: 'stop', isFirst: true })}
      </Box>
    </Box>
  )

  const settings = card(
    'settings',
    <Box flexDirection="column" rowGap={1}>
      <Box justifyContent="space-between" alignItems="center" columnGap={2}>
        <Box alignItems="center" columnGap={1} flexWrap="wrap">
          {icon('book', 'Guide', accent)}
          <Text bold>{`${view.guide} guide`}</Text>
          {ghost('guide', 'about', act.guide, {
            toggle: { isOpen: view.isGuideShown, opens: 'down' },
          })}
        </Box>
        {view.status}
      </Box>
      {view.isGuideShown && (
        <Box key="about">
          <Text dimColor wrap="wrap">
            {view.about}
          </Text>
        </Box>
      )}
      <Box key="divider" height={HAIR} backgroundColor={LINE} />
      {view.isRunning ? (
        loader
      ) : (
        <Box key="rows" flexDirection="column" rowGap={1}>
          {row(
            'Auto',
            // What Enter does as the switch stands is said in a small card
            // over the switch, and only while the pointer is on it: the
            // surface shows the card while this box, its nearest with a key,
            // is under the pointer. It stands above the switch, where what
            // it covers is drawn before it; under it, the next row's control
            // would be drawn across it.
            <Box key="auto-tip">
              {control(
                'auto-block',
                'auto',
                <Button key="auto" plain {...hotkeyOf('auto')} onPress={act.auto}>
                  {view.isOn ? 'On' : 'Off'}
                </Button>,
                {
                  borderStyle: 'round',
                  borderColor: view.isOn ? edge : LINE,
                  paddingX: 1.5,
                  paddingY: 0.25,
                  overflow: 'hidden',
                  ...(view.isOn ? { backgroundColor: tintOf(accent) } : {}),
                },
              )}
              <Box
                position="absolute"
                bottom={1}
                left={0}
                marginBottom={TIP_LIFT}
                display="none"
                hover={{ display: 'flex' }}
                borderStyle="round"
                borderColor={STRONG}
                backgroundColor={LIST}
                paddingX={1}
                paddingY={0.25}
              >
                <Text dimColor wrap="truncate">
                  {view.isOn
                    ? 'Enter polishes first and shows you before sending.'
                    : 'Enter sends right away, with no polish.'}
                </Text>
              </Box>
            </Box>,
          )}
          {row(
            'Session model',
            ghost('target', targetLabel, () => act.menu('target'), {
              toggle: { isOpen: view.open === 'target', opens: 'down' },
            }),
          )}
          {view.open === 'target' &&
            list(
              'target-list',
              options('target', view.targets, view.target, act.target),
            )}
          {row(
            'Polish model',
            ghost(
              'polisher',
              `${view.model} · ${view.effort}`,
              () => act.menu('polisher'),
              { toggle: { isOpen: view.open === 'polisher', opens: 'down' } },
            ),
          )}
          {view.open === 'polisher' && (
            <Box key="tuning" flexDirection="column" rowGap={1}>
              {list(
                'polisher-list',
                options(
                  'model',
                  view.models.map(value => ({ value, label: value })),
                  view.model,
                  act.model,
                ),
              )}
              {efforts}
              <Box key="polisher-foot" justifyContent="flex-end">
                {ghost('polisher-done', 'done', act.done)}
              </Box>
            </Box>
          )}
        </Box>
      )}
    </Box>,
  )

  const prompt = (
    key: string,
    name: string,
    text: string,
    isPolished: boolean,
    beside: JSX.Children,
  ) =>
    card(
      key,
      <Box flexDirection="column" rowGap={1}>
        <Box justifyContent="space-between" alignItems="center" columnGap={2}>
          <Text bold {...(isPolished ? { color: BLUE } : { dimColor: true })}>
            {name}
          </Text>
          <Box alignItems="center" columnGap={2}>
            {beside}
            <Text color="subtle">{`${text.trim().length} chars`}</Text>
          </Box>
        </Box>
        <Text dimColor={!isPolished} wrap="wrap">
          {text.trim()}
        </Text>
      </Box>,
      isPolished ? { borderColor: BLUE, backgroundColor: WASH } : {},
    )

  // The versions a retry has made of the draft, paged through as
  // assistant-ui's BranchPicker pages a message's branches. With one version
  // there is nothing to page, and at either end the arrow is no button.
  const arrow = (key: 'older' | 'newer', glyph: string, by: -1 | 1) => {
    const next = view.version + by

    return next < 0 || next >= view.versions ? (
      <Box paddingX={1} paddingY={0.5}>
        <Text color="subtle">{glyph}</Text>
      </Box>
    ) : (
      control(
        `${key}-set`,
        key,
        <Button key={key} plain {...hotkeyOf(key)} onPress={() => act.step(by)}>
          {glyph}
        </Button>,
        { paddingX: 1, paddingY: 0.5 },
      )
    )
  }
  // While a polish runs it is gone with the working row.
  const pager =
    view.versions > 1 && !view.isRunning ? (
      <Box key="versions" alignItems="center" flexShrink={0}>
        {arrow('older', '‹', -1)}
        <Text dimColor>{`${view.version + 1} / ${view.versions}`}</Text>
        {arrow('newer', '›', 1)}
      </Box>
    ) : null

  const review =
    view.preview === null ? null : (
      <Box key="review" flexDirection="column" rowGap={1}>
        {prompt('original', 'Original Prompt', view.draft ?? '', false, null)}
        {prompt('polished', 'Polished Prompt', view.preview, true, pager)}
      </Box>
    )

  // The working row, as assistant-ui's ActionBar stands under a message: what
  // to do with the polish on show, or the one button that makes one. While a
  // polish runs it is gone, and Stop stands with the loading mark.
  const actions = view.isRunning ? null : (
    <Box key="action-row" alignItems="center" columnGap={1} rowGap={1} flexWrap="wrap">
      {view.preview !== null &&
        filled('apply', 'Apply Polish', 'check', act.apply, true)}
      {view.preview !== null &&
        ghost('refresh', 'Retry Polish', act.retry, { before: 'retry' })}
      {view.preview !== null &&
        ghost('discard', 'Keep Original', act.keep, { before: 'close' })}
      {view.preview === null &&
        filled('polish', 'Prompt Polish', 'wand', act.polish)}
      {view.preview === null &&
        view.draft !== null &&
        ghost('restore', 'Undo Apply', act.undo, { before: 'undo' })}
    </Box>
  )

  // One row of the record: a dot in the color of what was done, when, what,
  // and a word on it.
  const entry = (line: LogLine) => (
    <Box alignItems="center" columnGap={1}>
      <Text color={view.kinds[line.kind].color}>●</Text>
      <Text color="subtle">{fmtClock(line.at)}</Text>
      <Text>{view.kinds[line.kind].label}</Text>
      <Text dimColor wrap="truncate">
        {line.text}
      </Text>
    </Box>
  )
  const latest = view.recent.at(-1)

  const foot = (
    <Box key="foot" flexDirection="column" rowGap={1}>
      {view.isKeysShown &&
        card(
          'keys-list',
          <Box flexDirection="column" rowGap={1}>
            <Text color="subtle" wrap="wrap">
              Keys work while this list is open. Click the pane first.
            </Text>
            <Box columnGap={3} flexWrap="wrap">
              {view.keys.map(([key, what]) => (
                <Text>
                  <Text color={edge} bold>
                    {key}
                  </Text>
                  <Text dimColor>{` ${what}`}</Text>
                </Text>
              ))}
            </Box>
          </Box>,
        )}
      {view.isLogShown &&
        card(
          'log-list',
          <Box flexDirection="column">
            {view.count === 0 && <Text color="subtle">No history yet</Text>}
            {view.recent.map(entry)}
          </Box>,
        )}
      <Box key="log-row" alignItems="center" justifyContent="space-between" columnGap={2}>
        <Box alignItems="center" columnGap={1}>
          {ghost('log', `History ${view.count}`, act.log, {
            toggle: { isOpen: view.isLogShown, opens: 'up' },
          })}
          {!view.isLogShown && latest !== undefined && (
            <Text color="subtle" wrap="truncate">
              {`${fmtClock(latest.at)} ${view.kinds[latest.kind].label} · ${latest.text}`}
            </Text>
          )}
        </Box>
        {ghost('keys', 'Keys', act.keys, {
          toggle: { isOpen: view.isKeysShown, opens: 'up' },
        })}
      </Box>
    </Box>
  )

  return (
    <Box
      key="pane"
      flexDirection="column"
      rowGap={1.5}
      {...(isDocked ? { minHeight: Math.max(1, bodyRows) } : {})}
    >
      {settings}
      {review}
      {actions}
      {isDocked && <Box key="spacer" flexGrow={1} />}
      {foot}
    </Box>
  )
}

